package com.aistock.notification.inbox;
import com.aistock.common.*;import com.aistock.notification.alert.*;import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.Cookie;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class InboxSecurityTest {
 InboxService service;NotificationAccess access;MockMvc mvc;UUID owner=UUID.randomUUID(),id=UUID.randomUUID();
 @BeforeEach void setup(){service=mock(InboxService.class);access=mock(NotificationAccess.class);when(access.resolve("session")).thenReturn(owner);mvc=MockMvcBuilders.standaloneSetup(new InboxController(service),new AlertTriggerController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new NotificationSecurityFilter(access,new ObjectMapper(),"http://localhost:15173")).build();}
 MockHttpServletRequestBuilder auth(MockHttpServletRequestBuilder r){return r.cookie(new Cookie("AISTOCK_SESSION","session"));}
 MockHttpServletRequestBuilder write(MockHttpServletRequestBuilder r){return auth(r).cookie(new Cookie("XSRF-TOKEN","csrf")).header("X-XSRF-TOKEN","csrf").header("Origin","http://localhost:15173").contentType("application/json");}
 @Test void anonymousDeniedAndForgedHeaderNeverSelectsOwner()throws Exception{mvc.perform(get("/api/v1/messages")).andExpect(status().isUnauthorized());mvc.perform(auth(get("/api/v1/messages")).header("X-User-Id",UUID.randomUUID())).andExpect(status().isOk());verify(service).list(owner,1,20,false);}
 @Test void administratorSessionStillUsesItsOwnIdentity()throws Exception{UUID admin=UUID.randomUUID();when(access.resolve("admin")).thenReturn(admin);mvc.perform(get("/api/v1/messages").cookie(new Cookie("AISTOCK_SESSION","admin")).header("X-User-Id",owner)).andExpect(status().isOk());verify(service).list(admin,1,20,false);}
 @Test void writesRequireOriginAndCsrf()throws Exception{mvc.perform(auth(patch("/api/v1/messages/"+id+"/read")).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(write(post("/api/v1/messages/read")).header("Origin","http://evil.example").content("{}" )).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void queryValidationIsStrict()throws Exception{for(String query:new String[]{"page=0","page=1.0","size=51","unreadOnly=yes","ownerId="+owner,"page=1&page=2"})mvc.perform(auth(get("/api/v1/messages?"+query))).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void invalidIdsBodiesAndBatchesNeverReachService()throws Exception{for(String body:new String[]{"{}","[]","{\"ids\":[]}","{\"ids\":[\"1-1-1-1-1\"]}","{\"ids\":[\""+id+"\",\""+id+"\"]}","{\"ids\":[\""+id+"\"],\"ownerId\":\""+owner+"\"}"})mvc.perform(write(post("/api/v1/messages/read")).content(body)).andExpect(status().isBadRequest());mvc.perform(write(patch("/api/v1/messages/"+id+"/read")).content("{\"ownerId\":\"forged\"}")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void exactPathsAndMethodsOnly()throws Exception{for(String path:new String[]{"/api/v1/messages;evil","/api/v1/messages%2Funread-count","/api/v1/messages/"+id+"/read;evil","/api/v1/alerts/"+id+"/triggers;evil"})mvc.perform(auth(get(path))).andExpect(status().isNotFound());mvc.perform(write(post("/api/v1/messages")).content("{}")).andExpect(status().isNotFound());verifyNoInteractions(service);}
 @Test void validRoutesDispatchOnlyVerifiedOwner()throws Exception{mvc.perform(auth(get("/api/v1/messages?unreadOnly=true&size=3"))).andExpect(status().isOk());mvc.perform(auth(get("/api/v1/messages/unread-count"))).andExpect(status().isOk());mvc.perform(auth(get("/api/v1/alerts/"+id+"/triggers"))).andExpect(status().isOk());mvc.perform(write(patch("/api/v1/messages/"+id+"/read")).content("{}")).andExpect(status().isOk());mvc.perform(write(post("/api/v1/messages/read")).content("{\"ids\":[\""+id+"\"]}")).andExpect(status().isOk());verify(service).list(owner,1,3,true);verify(service).unreadCount(owner);verify(service).triggers(owner,id,1,20);verify(service).read(owner,id);verify(service).readBatch(owner,List.of(id));}
}
